// Learning outcomes parsed from the official Cambridge syllabus PDF (see R2O.SYLS.addmath.url).
// Generated by a script; wording is Cambridge's, page numbers are the PDF pages.
window.R2O = window.R2O || {};
R2O.SYLS = R2O.SYLS || {};
R2O.SYLS.addmath = Object.assign(R2O.SYLS.addmath || {}, { objectives: [
    {"id": "1.1", "a": 0, "p": 11, "t": "Understand the terms: function, domain, range (image set), one–one function, many–one…", "los": ["Understand the terms: function, domain, range (image set), one–one function, many–one function, inverse function and composition of functions. Includes explaining in words why a given function is a function."]},
    {"id": "1.2", "a": 0, "p": 11, "t": "Find the domain and range of functions", "los": ["Find the domain and range of functions. Includes inverse functions and composite functions. The domain of f may need to be restricted for f –1 and/or gf to exist. Domain gf ⊆ Domain f Range gf ⊆ Range g"]},
    {"id": "1.3", "a": 0, "p": 12, "t": "Recognise and use function notation", "los": ["Recognise and use function notation. Examples include: • f(x) = 2ex • f : x ↦ lg x, for x > 0 • f –1(x) • fg(x) [= f(g(x))] • f 2(x) [= f(f(x))] The notation f 2(x) will not be used with trigonometric functions."]},
    {"id": "1.4", "a": 0, "p": 12, "t": "Understand the relationship between y = f(x) and y = |f(x)|, where f(x) may be linear,…", "los": ["Understand the relationship between y = f(x) and y = |f(x)|, where f(x) may be linear, quadratic, cubic or trigonometric. If f(x) is trigonometric it will be one of the following: • y = a sin bx + c • y = a cos bx + c • y = a tan bx + c where a is a positive integer, b is a simple fraction or integer, and c is an integer. Fractions will have a denominator of 2, 3, 4, 6 or 8 only."]},
    {"id": "1.5", "a": 0, "p": 12, "t": "Explain in words why a given function does not have an inverse", "los": ["Explain in words why a given function does not have an inverse."]},
    {"id": "1.6", "a": 0, "p": 12, "t": "Find the inverse of a one–one function", "los": ["Find the inverse of a one–one function. Correct notation must be used. For example: • f(x) = e2x • f –1(x) = 2 1 ln x"]},
    {"id": "1.7", "a": 0, "p": 12, "t": "Form and use composite functions", "los": ["Form and use composite functions. Understand that order of functions is important, i.e. fg may not be the same as gf ."]},
    {"id": "1.8", "a": 0, "p": 12, "t": "Use sketch graphs to show the relationship between a function and its inverse", "los": ["Use sketch graphs to show the relationship between a function and its inverse. Understand that each function is the reflection of the other in the line y = x."]},
    {"id": "2.1", "a": 1, "p": 12, "t": "Find the maximum or minimum value of the quadratic function f : x ↦ ax2 + bx + c by…", "los": ["Find the maximum or minimum value of the quadratic function f : x ↦ ax2 + bx + c by completing the square or by differentiation."]},
    {"id": "2.2", "a": 1, "p": 12, "t": "Use the maximum or minimum value of f(x) to sketch the graph of y = f(x) or determine…", "los": ["Use the maximum or minimum value of f(x) to sketch the graph of y = f(x) or determine the range for a given domain. Candidates should use correct notation to write a domain or range."]},
    {"id": "2.3", "a": 1, "p": 12, "t": "Know the conditions for f(x) = 0 to have: (i) two real roots (ii) two equal roots…", "los": ["Know the conditions for f(x) = 0 to have: (i) two real roots (ii) two equal roots (iii) no real roots and the related conditions for a given line to: (i) intersect a given curve (ii) be a tangent to a given curve (iii) not intersect a given curve. Understand how the discriminant relates to the roots of the equation."]},
    {"id": "2.4", "a": 1, "p": 13, "t": "Solve quadratic equations for real roots", "los": ["Solve quadratic equations for real roots. Formula is given in the List of formulas. Students are expected to be able to use factorisation, the quadratic formula and completing the square. On the calculator paper, correct answers are acceptable without working."]},
    {"id": "2.5", "a": 1, "p": 13, "t": "Find the solution set for quadratic inequalities either graphically or algebraically", "los": ["Find the solution set for quadratic inequalities either graphically or algebraically. Solutions should be written in the correct form. For example: • –3 < x < 4 • x < 1 or x > 6"]},
    {"id": "3.1", "a": 2, "p": 13, "t": "Know and use the remainder and factor theorems", "los": ["Know and use the remainder and factor theorems."]},
    {"id": "3.2", "a": 2, "p": 13, "t": "Find factors of polynomials", "los": ["Find factors of polynomials. For a cubic polynomial, students are first expected to obtain a product of a linear factor and a quadratic factor, for example by observation or by algebraic long division."]},
    {"id": "3.3", "a": 2, "p": 13, "t": "Solve cubic equations", "los": ["Solve cubic equations."]},
    {"id": "4.1", "a": 3, "p": 13, "t": "Solve equations of the type • |ax + b| = c (c ⩾ 0) • |ax + b| = cx + d • |ax + b| =…", "los": ["Solve equations of the type • |ax + b| = c (c ⩾ 0) • |ax + b| = cx + d • |ax + b| = |cx + d| • |ax2 + bx + c| = d using algebraic or graphical methods. For graphical solutions, an accurate graph is expected. For algebraic methods, any valid method is acceptable."]},
    {"id": "4.2", "a": 3, "p": 13, "t": "Solve graphically or algebraically inequalities of the type • k|ax + b| > c (c ⩾ 0) •…", "los": ["Solve graphically or algebraically inequalities of the type • k|ax + b| > c (c ⩾ 0) • k|ax + b| ⩽ c (c > 0) • k|ax + b| ⩽ |cx + d| where k > 0 • |ax + b| ⩽ cx + d • |ax2 + bx + c| > d • |ax2 + bx + c| ⩽ d For graphical solutions, an accurate graph is expected. For algebraic methods, any valid method is acceptable."]},
    {"id": "4.3", "a": 3, "p": 14, "t": "Use substitution to form and solve a quadratic equation in order to solve a related…", "los": ["Use substitution to form and solve a quadratic equation in order to solve a related equation. For example: • an equation in √x • 2(ln 5x)2 + ln 5x – 6 = 0 • 3ex = 12 – 5e–x Candidates are expected to identify the appropriate substitution."]},
    {"id": "4.4", "a": 3, "p": 14, "t": "Sketch the graphs of cubic polynomials and their moduli, when given as a product of…", "los": ["Sketch the graphs of cubic polynomials and their moduli, when given as a product of three linear factors. The points of intersection of the graph with the coordinate axes should be clearly labelled."]},
    {"id": "4.5", "a": 3, "p": 14, "t": "Solve graphically cubic inequalities of the form • f(x) ⩾ d • f(x) > d • f(x) ⩽ d •…", "los": ["Solve graphically cubic inequalities of the form • f(x) ⩾ d • f(x) > d • f(x) ⩽ d • f(x) < d where f(x) is a product of three linear factors and d is a constant."]},
    {"id": "5.1", "a": 4, "p": 14, "t": "Solve simultaneous equations in two unknowns by elimination or substitution", "los": ["Solve simultaneous equations in two unknowns by elimination or substitution. For example: • y – x + 3 = 0 and x2 – 3xy + y2 + 19 = 0 • xy2 = 4 and xy = 3"]},
    {"id": "6.1", "a": 5, "p": 14, "t": "Know and use simple properties and graphs of the logarithmic and exponential…", "los": ["Know and use simple properties and graphs of the logarithmic and exponential functions, including ln x and ex. Logarithms may be given to any base. Understand that f(x) = ex and g(x) = ln x are each the inverse of the other. Understand the asymptotic nature of the graphs of logarithmic and exponential functions. State the equations of any asymptotes. Graphs are limited to y = kenx + a and y = k ln(ax + b) where n, k, a and b are integers. Series expansions are not required."]},
    {"id": "6.2", "a": 5, "p": 15, "t": "Know and use the laws of logarithms, including change of base of logarithms", "los": ["Know and use the laws of logarithms, including change of base of logarithms. For example: • Write 3 + 2 lg p – lg q as a single base 10 logarithm."]},
    {"id": "6.3", "a": 5, "p": 15, "t": "Solve equations of the form ax = b", "los": ["Solve equations of the form ax = b."]},
    {"id": "7.1", "a": 6, "p": 15, "t": "Use the equation of a straight line", "los": ["Use the equation of a straight line."]},
    {"id": "7.2", "a": 6, "p": 15, "t": "Know and use the condition for two lines to be parallel or perpendicular", "los": ["Know and use the condition for two lines to be parallel or perpendicular."]},
    {"id": "7.3", "a": 6, "p": 15, "t": "Solve problems involving midpoint and length of a line, including finding and using…", "los": ["Solve problems involving midpoint and length of a line, including finding and using the equation of a perpendicular bisector."]},
    {"id": "7.4", "a": 6, "p": 15, "t": "Transform given relationships to and from straight-line form, including determining…", "los": ["Transform given relationships to and from straight-line form, including determining unknown constants by calculating the gradient or intercept of the transformed graph. For example: • To straight-line form y = Axn y = Abx • From straight-line form to an equation of the form y2 = Ax3 + B e2y = Ax2 + B y3 = Aln x + B"]},
    {"id": "8.1", "a": 7, "p": 15, "t": "Know and use the equation of a circle with radius r and centre (a, b)", "los": ["Know and use the equation of a circle with radius r and centre (a, b). Identify the centre and radius of a circle using a circle equation in any form. For example: • (x – a)2 + (y – b)2 = r2 • x2 + y2 + 2gx + 2fy + c = 0 Formula is given in the List of formulas."]},
    {"id": "8.2", "a": 7, "p": 15, "t": "Solve problems involving the intersection of a circle and a straight line", "los": ["Solve problems involving the intersection of a circle and a straight line. Includes finding points of intersection. Includes determining whether a straight line: • is a tangent • is a chord • does not intersect the circle."]},
    {"id": "8.3", "a": 7, "p": 16, "t": "Solve problems involving tangents to a circle", "los": ["Solve problems involving tangents to a circle. Includes finding equations of tangents. No use of calculus is expected."]},
    {"id": "8.4", "a": 7, "p": 16, "t": "Solve problems involving the intersection of two circles", "los": ["Solve problems involving the intersection of two circles. Includes finding points of intersection, finding the equation of a common chord or determining whether two circles: • intersect • touch • do not intersect."]},
    {"id": "9.1", "a": 8, "p": 16, "t": "Solve problems involving the arc length and sector area of a circle, including…", "los": ["Solve problems involving the arc length and sector area of a circle, including knowledge and use of radian measure. Use of radian measure is expected in the solution of problems which may involve compound shapes. Formulas are not given."]},
    {"id": "10.1", "a": 9, "p": 16, "t": "Know and use the six trigonometric functions of angles of any magnitude", "los": ["Know and use the six trigonometric functions of angles of any magnitude. sine, cosine, tangent, secant, cosecant, cotangent"]},
    {"id": "10.2", "a": 9, "p": 16, "t": "Understand and use the amplitude and period of a trigonometric function, including the…", "los": ["Understand and use the amplitude and period of a trigonometric function, including the relationship between graphs of related trigonometric functions. For example: y = sin x and y = 3sin 2x The period may be in either degrees or radians."]},
    {"id": "10.3", "a": 9, "p": 16, "t": "Draw and use the graphs of y = a sin bx + c y = a cos bx + c y = a tan bx + c where a…", "los": ["Draw and use the graphs of y = a sin bx + c y = a cos bx + c y = a tan bx + c where a is a positive integer, b is a simple fraction or integer, and c is an integer. Graphs will be drawn over a given domain which may be in either degrees or radians. For a graph of y = a tan bx + c, the x-coordinate of any asymptote should be clearly labelled. Fractions will have a denominator of 2, 3, 4, 6 or 8 only."]},
    {"id": "10.4", "a": 9, "p": 16, "t": "Use the relationships: • sin2 A + cos2 A = 1 • sec2 A = 1 + tan2 A • cosec2 A = 1 +…", "los": ["Use the relationships: • sin2 A + cos2 A = 1 • sec2 A = 1 + tan2 A • cosec2 A = 1 + cot2 A Trigonometric identities are given in the List of formulas."]},
    {"id": "10.5", "a": 9, "p": 17, "t": "Solve, for a given domain, trigonometric equations involving the six trigonometric…", "los": ["Solve, for a given domain, trigonometric equations involving the six trigonometric functions. Includes the use of the relationships in 10.4. For example: • 4 cot θ = tan θ • 2 sec2 θ + tan θ – 3 = 0"]},
    {"id": "10.6", "a": 9, "p": 17, "t": "Prove trigonometric relationships involving the six trigonometric functions", "los": ["Prove trigonometric relationships involving the six trigonometric functions. Includes the use of the relationships in 10.4. For example: • sin x tan x + cos x = sec x • sin θ ÷ (1 + cos θ) + (1 + cos θ) ÷ sin θ = 2 cosec θ"]},
    {"id": "11.1", "a": 10, "p": 17, "t": "Recognise the difference between permutations and combinations and know when each…", "los": ["Recognise the difference between permutations and combinations and know when each should be used."]},
    {"id": "11.2", "a": 10, "p": 17, "t": "Know and use the notation n! and the expressions for permutations and combinations of…", "los": ["Know and use the notation n! and the expressions for permutations and combinations of n items taken r at a time. Includes 0! = 1."]},
    {"id": "11.3", "a": 10, "p": 17, "t": "Solve problems on arrangement and selection using permutations or combinations", "los": ["Solve problems on arrangement and selection using permutations or combinations. Problems will be either in an everyday context or based on an algebraic problem. Problems involving: • repetition of objects • objects arranged in a circle • both permutations and combinations, are not included."]},
    {"id": "12.1", "a": 11, "p": 18, "t": "Use the binomial theorem for expansion of (a + b)n for positive integer n", "los": ["Use the binomial theorem for expansion of (a + b)n for positive integer n. Includes simplification of coefficients. Formula is given in the List of formulas."]},
    {"id": "12.2", "a": 11, "p": 18, "t": "Use the general term ⁿCᵣ aⁿ⁻ʳ bʳ, 0 ⩽ r ⩽ n. For example: Find the term…", "los": ["Use the general term ⁿCᵣ aⁿ⁻ʳ bʳ, 0 ⩽ r ⩽ n. For example: Find the term independent of x in a binomial expansion. Knowledge of the greatest term and properties of the coefficients is not required."]},
    {"id": "12.3", "a": 11, "p": 18, "t": "Recognise arithmetic and geometric progressions and understand the difference between them", "los": ["Recognise arithmetic and geometric progressions and understand the difference between them."]},
    {"id": "12.4", "a": 11, "p": 18, "t": "Use the formulas for the nth term and for the sum of the first n terms to solve…", "los": ["Use the formulas for the nth term and for the sum of the first n terms to solve problems involving arithmetic or geometric progressions. Problems may be in context. Formulas are given in the List of formulas."]},
    {"id": "12.5", "a": 11, "p": 18, "t": "Use the condition for the convergence of a geometric progression, and the formula for…", "los": ["Use the condition for the convergence of a geometric progression, and the formula for the sum to infinity of a convergent geometric progression. Includes explaining why a particular geometric progression has or does not have a sum to infinity. Formula is given in the List of formulas."]},
    {"id": "13.1", "a": 12, "p": 18, "t": "Understand and use vector notation", "los": ["Understand and use vector notation. Vectors will be given in any form including: column vectors, AB→, bold letters such as p, and ai – bj. Candidates are expected to use correct vector notation."]},
    {"id": "13.2", "a": 12, "p": 18, "t": "Know and use position vectors and unit vectors", "los": ["Know and use position vectors and unit vectors. For example: The unit vector in the same direction as a is a ÷ |a|."]},
    {"id": "13.3", "a": 12, "p": 18, "t": "Find the magnitude of a vector; add and subtract vectors and multiply vectors by scalars", "los": ["Find the magnitude of a vector; add and subtract vectors and multiply vectors by scalars. Includes: • equating like vectors • solving problems using vector geometry, with a diagram given in more complex cases."]},
    {"id": "13.4", "a": 12, "p": 18, "t": "Compose and resolve velocities", "los": ["Compose and resolve velocities. Determine a resultant vector by adding two or more vectors together. Includes the use of a velocity vector to determine position and solve problems in context such as particles colliding."]},
    {"id": "14.1", "a": 13, "p": 19, "t": "Understand the idea of a derived function", "los": ["Understand the idea of a derived function. Only an informal understanding of the idea of a limit is expected, and the technique of differentiation from first principles is not required."]},
    {"id": "14.2", "a": 13, "p": 19, "t": "Use the notations f′(x), f″(x), dy/dx, d²y/dx²", "los": ["Use the notations f′(x), f″(x), dy/dx, d²y/dx² [= d/dx (dy/dx)], δx, δx → 0, δy/δx."]},
    {"id": "14.3", "a": 13, "p": 19, "t": "Know and use the derivatives of the standard functions xn (for any rational n), sin x,…", "los": ["Know and use the derivatives of the standard functions xn (for any rational n), sin x, cos x, tan x, ex, ln x. Includes constant multiples, sums and composite functions (use of chain rule). For example, differentiate a power of a bracket using the chain rule. For trigonometric functions angles will always be in radians."]},
    {"id": "14.4", "a": 13, "p": 19, "t": "Differentiate products and quotients of functions", "los": ["Differentiate products and quotients of functions."]},
    {"id": "14.5", "a": 13, "p": 19, "t": "Use differentiation to find gradients, tangents and normals", "los": ["Use differentiation to find gradients, tangents and normals."]},
    {"id": "14.6", "a": 13, "p": 19, "t": "Use differentiation to find stationary points", "los": ["Use differentiation to find stationary points. Points of inflexion are not included."]},
    {"id": "14.7", "a": 13, "p": 19, "t": "Apply differentiation to connected rates of change, small increments and approximations", "los": ["Apply differentiation to connected rates of change, small increments and approximations."]},
    {"id": "14.8", "a": 13, "p": 19, "t": "Apply differentiation to practical problems involving maxima and minima", "los": ["Apply differentiation to practical problems involving maxima and minima."]},
    {"id": "14.9", "a": 13, "p": 19, "t": "Use the first and second derivative tests to discriminate between maxima and minima", "los": ["Use the first and second derivative tests to discriminate between maxima and minima. Points of inflexion are not included. Full justification of conclusions is expected. An explanation of how to distinguish between a maximum point and a minimum point may be required. Unless specified otherwise, any valid method is allowed."]},
    {"id": "14.10", "a": 13, "p": 19, "t": "Understand integration as the reverse process of differentiation", "los": ["Understand integration as the reverse process of differentiation. Solutions for indefinite integrals should include an arbitrary constant."]},
    {"id": "14.11", "a": 13, "p": 19, "t": "Integrate sums of terms in powers of x, including 1/x and 1/(ax + b). Solutions for…", "los": ["Integrate sums of terms in powers of x, including 1/x and 1/(ax + b). Solutions for indefinite integrals should include an arbitrary constant."]},
    {"id": "14.12", "a": 13, "p": 20, "t": "Integrate functions of the form: • (ax + b)n for any rational n • sin (ax + b) • cos…", "los": ["Integrate functions of the form: • (ax + b)n for any rational n • sin (ax + b) • cos (ax + b) • sec2 (ax + b) • eax+b Includes the case where n = –1. For trigonometric functions angles will always be in radians. Solutions for indefinite integrals should include an arbitrary constant."]},
    {"id": "14.13", "a": 13, "p": 20, "t": "Evaluate definite integrals and apply integration to the evaluation of plane areas", "los": ["Evaluate definite integrals and apply integration to the evaluation of plane areas. Plane areas include: • between a line and a curve • between two curves • a sum of two areas."]},
    {"id": "14.14", "a": 13, "p": 20, "t": "Apply differentiation and integration to kinematics problems that involve…", "los": ["Apply differentiation and integration to kinematics problems that involve displacement, velocity and acceleration of a particle moving in a straight line with variable or constant acceleration. For example: Given the velocity of a particle is v = 3t2 – 30t + 72 find its acceleration when t = 2."]},
    {"id": "14.15", "a": 13, "p": 20, "t": "Make use of the relationships in 14.14 to draw and use the following graphs: •…", "los": ["Make use of the relationships in 14.14 to draw and use the following graphs: • displacement–time • distance–time • velocity–time • speed–time • acceleration–time. For example: A particle moves in a straight line. Its displacement s, from a fixed point at time, t, is given by s = 3t3 – 10t2 + 4t + 8 for 0 ⩽ t ⩽ 3. Sketch its displacement–time graph, its speed–time graph, its acceleration–time graph."]}
  ] });
